import React, { FunctionComponent, useCallback } from 'react';
import { ClickableDiv } from '../../atoms';

import './index.less';

interface TagProps {
  text: string;
  onClose: (text) => any;
}

interface TagsListProps {
  listItems: string[];
  onClose: (text) => any;
}

export const Tag: FunctionComponent<TagProps> = ({ text, onClose }) => {
  const handleClick = useCallback(() => {
    onClose(text);
  }, [text, onClose]);

  return (
    <div className="tag-wrapper">
      <div className="tag-text">{text}</div>
      <ClickableDiv className="icon-x tag-icon" onClick={handleClick} aria-label="Remove" />
    </div>
  );
};

export const TagsList: FunctionComponent<TagsListProps> = ({ listItems, onClose }) => (
  <div className="tags-list">
    {listItems.map((itemText) => (
      <Tag text={itemText} onClose={onClose} key={itemText} />
    ))}
  </div>
);
